  { name: "CLI, SDKs & registry", icon: "book", file: "crates/cli; crates/guest; sdk; registry", role: "Turn authoring contracts into deployable apps and typed clients.", input: "statex.toml, WIT, migrations, implementations and workspace layout.", output: "Wasm, manifests, generated caller bindings, Python clients and registry entries.", details: "The CLI scaffolds Rust/Python apps, builds and verifies them, checks compatibility, syncs call interfaces, and deploys. Guest SDKs expose host capabilities; the Python client SDK invokes the generic HTTP API.", boundary: "The registry describes APIs for development. Live actor placement comes from owner.json, not the registry." }
