  { title: "Counters & account state", kind: "Repository example", icon: "database", key: "counter/alice · account/alice", text: "A small entity has multiple related updates and a natural key. Serialize increments, balances, or history in its own database.", boundary: "One account call is atomic. A transfer between two account actors is not automatically a transaction.", source: "examples/counter/src/lib.rs; examples/python-counter" },
  { title: "Configuration & key/value", kind: "Repository example", icon: "layers", key: "kv/defaults · config/checkout", text: "Use per-key durable state and typed cross-app calls. The demo configuration and Rust counter apps interact with the demo database app.", boundary: "A config read through another actor is a separate call, not a shared SQLite connection or cross-app SQL join.", source: "apps/demo/config; apps/demo/db; apps/demo/rustdemo/src/lib.rs" },
  { title: "Relay / typed composition", kind: "Repository example", icon: "branch", key: "relay/checkout", text: "A relay actor calls counters, accounts, or other relay actors through generated typed interfaces. This demonstrates composition and failure mapping.", boundary: "The relay's local record can roll back while a called counter or account already committed.", source: "examples/caller; examples/python-caller" },
  { title: "Shopping cart", kind: "Application design", icon: "cube", key: "cart/customer-204", text: "Keep line items, coupon decisions, and the cart version together. A call can atomically modify several local tables before replying.", boundary: "Inventory reservations and payment authorization need idempotent cross-actor/external protocols.", source: "Derived from the per-actor transaction model" },
  { title: "Session or conversation", kind: "Application design", icon: "book", key: "conversation/session-73", text: "Persist messages, workflow state, preferences, and request deduplication for an individual session. Different sessions can progress independently.", boundary: "An idle actor is evicted. Durable data survives, but sockets, streams and in-memory continuations do not.", source: "Derived from activation and idle-eviction behavior" },
  { title: "Reservations & quotas", kind: "Application design", icon: "shield", key: "quota/tenant-5 · room/204", text: "Enforce an invariant within one chosen key: reserve a slot only if capacity remains, or debit a quota with the request ledger in the same transaction.", boundary: "A hot global quota key is a serialized bottleneck. Sharding changes the invariant and requires a reconciliation protocol.", source: "Derived from serialized actor calls + SQLite" }
